<article class="thread-item"><a href="<?= e(url('user',['id'=>(int)$entry['author_id']])) ?>"><?= avatar($entry) ?></a><div class="grow"><div class="thread-meta"><span><?= e($entry['category_name'] ?: tr('Community')) ?></span><?php if ($entry['pinned']): ?><span class="pill"><?= t('Pinned') ?></span><?php endif ?></div><h3 class="thread-title"><a href="<?= e(item_url($entry)) ?>"><?= e($entry['title']) ?></a></h3><p class="thread-excerpt"><?= e($entry['excerpt']) ?></p><div class="thread-meta"><?php if ($s->get('show_authors')): ?><span><?= e($entry['display_name']) ?></span><?php endif ?><?php if ($s->get('show_dates')): ?><time><?= dt((int)$entry['created_at']) ?></time><?php endif ?></div></div><?php if ($s->get('show_stats')): ?><div class="thread-count"><strong><?= (int)$entry['view_count'] ?></strong><span><?= t('Views') ?></span></div><?php endif ?></article>
